import{_ as o,o as d,c as a,ak as i}from"./chunks/framework.DpBHfSJD.js";const u=JSON.parse('{"title":"Rendering 渲染","description":"","frontmatter":{"title":"Rendering 渲染","prev":false,"next":false},"headers":[],"relativePath":"posts/docs/rendering/index.md","filePath":"posts/docs/rendering/index.md","lastUpdated":1777881468000}'),t={name:"posts/docs/rendering/index.md"};function l(r,e,c,n,s,h){return d(),a("div",null,[...e[0]||(e[0]=[i(`<h1 id="渲染模块-rendering-module" tabindex="-1">渲染模块 (Rendering Module) <a class="header-anchor" href="#渲染模块-rendering-module" aria-label="Permalink to “渲染模块 (Rendering Module)”">​</a></h1><p>包 <code>dev.anvilcraft.lib.v2.rendering</code> 提供了泛光（Bloom）后处理效果以及一套通用的 UBO（Uniform Buffer Object）布局定义框架，并通过 Mixin 集成到 Minecraft 的 GUI 渲染和主渲染流程中。</p><hr><h2 id="_1-模块概述" tabindex="-1">1. 模块概述 <a class="header-anchor" href="#_1-模块概述" aria-label="Permalink to “1. 模块概述”">​</a></h2><ul><li><strong>主类</strong>：<code>ALRendering</code> – 模组入口，负责创建管线、注册事件。</li><li><strong>后处理效果</strong>：<code>BloomPostEffect</code> – 实现泛光效果的完整多 Pass 处理链。</li><li><strong>UBO 框架</strong>：位于 <code>foundation.ubo</code> 包，提供类型安全的 ST140 布局定义。</li><li><strong>着色器</strong>：位于资源目录，包括 <code>blit.vsh</code>（顶点）、<code>blur.fsh</code>、<code>apply_bloom.fsh</code>、<code>down_sample.fsh</code>、<code>up_sample.fsh</code> 及辅助 <code>util.glsl</code>。</li><li><strong>Mixin</strong>：<code>GuiRendererMixin</code> 和 <code>MinecraftMixin</code> 用于在渲染流程中嵌入泛光处理，并支持 GUI 元素的额外 UBO 绑定。</li><li><strong>测试/调试</strong>：<code>ALRTest</code> 提供示例（如渲染带泛光的物品），通过系统属性开启。</li></ul><hr><h2 id="_2-ubo-基础框架" tabindex="-1">2. UBO 基础框架 <a class="header-anchor" href="#_2-ubo-基础框架" aria-label="Permalink to “2. UBO 基础框架”">​</a></h2><p>UBO 系统用于在代码中声明 GLSL Uniform Block 的内存布局，并自动计算 STD140 大小和填充数据。</p><h3 id="_2-1-uboobject" tabindex="-1">2.1 UboObject <a class="header-anchor" href="#_2-1-uboobject" aria-label="Permalink to “2.1 UboObject”">​</a></h3><p>所有自定义 UBO 的抽象基类。</p><ul><li><strong><code>getDefinition()</code></strong>：子类必须实现，返回对应类型的 <code>UboLayoutDefinition</code>。</li><li><strong><code>upload(CommandEncoder, GpuBufferSlice)</code></strong>：将当前对象数据通过布局写入显存 Buffer 切片。</li></ul><h3 id="_2-2-ubolayoutdefinition" tabindex="-1">2.2 UboLayoutDefinition <a class="header-anchor" href="#_2-2-ubolayoutdefinition" aria-label="Permalink to “2.2 UboLayoutDefinition”">​</a></h3><p>泛型 <code>T</code> 布局定义，保存一组 <code>UboLayoutEntry</code>。</p><ul><li><strong><code>create(UboLayoutEntry...)</code></strong>：静态工厂，接受任意数量的条目。</li><li><strong><code>write(ByteBuffer, T)</code></strong>：按布局将对象字段写入 ByteBuffer。</li><li><strong><code>size()</code></strong>：返回整个 UBO 在 STD140 下的字节大小。</li></ul><h3 id="_2-3-ubolayoutentry" tabindex="-1">2.3 UboLayoutEntry <a class="header-anchor" href="#_2-3-ubolayoutentry" aria-label="Permalink to “2.3 UboLayoutEntry”">​</a></h3><p>记录条目 <code>(UboLayoutEntryType&lt;T&gt;, Function&lt;I, T&gt;)</code>，连接字段类型与 getter 方法。</p><ul><li><strong>静态工厂</strong>：<code>ofInt()</code>、<code>ofFloat()</code>、<code>ofVec2f()</code>、<code>ofVec3f()</code>、<code>ofVec4f()</code>、<code>ofMat4f()</code> 创建对应类型的 Builder。</li><li><strong><code>Builder&lt;T,I&gt;</code></strong>：链式调用 <code>.forGetter(Function&lt;I,T&gt;)</code> → <code>.build()</code> 生成条目。</li></ul><h3 id="_2-4-ubolayoutentrytype" tabindex="-1">2.4 UboLayoutEntryType <a class="header-anchor" href="#_2-4-ubolayoutentrytype" aria-label="Permalink to “2.4 UboLayoutEntryType”">​</a></h3><p>定义具体的 STD140 数据类型（FLOAT, VEC2, VEC3, VEC4, INT, MAT4），内部实现 <code>acceptSizeCalculator</code> 和 <code>acceptWriter</code> ，分别用于大小计算和写入。</p><hr><h2 id="_3-泛光后处理实现" tabindex="-1">3. 泛光后处理实现 <a class="header-anchor" href="#_3-泛光后处理实现" aria-label="Permalink to “3. 泛光后处理实现”">​</a></h2><h3 id="_3-1-bloomposteffect" tabindex="-1">3.1 BloomPostEffect <a class="header-anchor" href="#_3-1-bloomposteffect" aria-label="Permalink to “3.1 BloomPostEffect”">​</a></h3><p>核心类，管理泛光输入、下采样、上采样、模糊及混合的全过程。</p><h4 id="初始化" tabindex="-1">初始化 <a class="header-anchor" href="#初始化" aria-label="Permalink to “初始化”">​</a></h4><ul><li>构造函数可自定义泛光参数（强度、阈值、灵敏度等），内部创建 <code>BloomParametersUbo</code>、<code>BlurParametersUbo</code>、 <code>BloomPipelineParametersUbo</code> 和对应的 GPU Buffer。</li><li>根据窗口大小初始化 <code>downsampleTargets[]</code> 和 <code>upsampleTargets[]</code> 目标纹理。</li></ul><h4 id="主要方法" tabindex="-1">主要方法 <a class="header-anchor" href="#主要方法" aria-label="Permalink to “主要方法”">​</a></h4><ul><li><strong><code>beginFrame()</code></strong>：每帧开始时清理临时纹理和脏标记。</li><li><strong><code>drawBloomed(BloomRenderCallback)</code></strong>：注册需要在泛光输入纹理上额外绘制的物体。</li><li><strong><code>process(modelViewMatrix, featureRenderDispatcher)</code></strong>： <ol><li>执行所有 <code>BloomRenderCallback</code>（<code>runBloomDraws</code>），将其渲染到 <code>bloomInputTarget</code>。</li><li>下采样（<code>doDownSample</code>）—— 逐步缩小泛光纹理。</li><li>上采样（<code>doUpSample</code>）—— 逐步放大并与上层混合。</li><li>将最终泛光结果混合回主渲染目标（<code>applyBloom</code>）。</li></ol></li><li><strong><code>resize(width, height)</code></strong>：窗口大小变化时重新调整所有目标纹理和全屏四边形顶点缓冲。</li></ul><h4 id="内部-pass" tabindex="-1">内部 Pass <a class="header-anchor" href="#内部-pass" aria-label="Permalink to “内部 Pass”">​</a></h4><ul><li><strong>DownSample</strong>：每次将纹理缩小一半，使用 <code>DOWNSAMPLE</code> 管线。</li><li><strong>UpSample</strong>：采用高斯模糊（5×5 核），结合当前层和前一层纹理，使用 <code>UPSAMPLE</code> 管线。</li><li><strong>ApplyBloom</strong>：将泛光纹理与游戏主渲染纹理混合，公式 <code>color + bloom * pow(threshold, luminance * sensitivity)</code>，使用 <code>APPLY_BLOOM</code> 管线。</li></ul><h4 id="回调接口" tabindex="-1">回调接口 <a class="header-anchor" href="#回调接口" aria-label="Permalink to “回调接口”">​</a></h4><p><strong><code>BloomRenderCallback</code></strong>：函数式接口，<code>void render(SubmitNodeCollector, PoseStack)</code>，用于向泛光输入提交模型。</p><h3 id="_3-2-ubo-实现" tabindex="-1">3.2 UBO 实现 <a class="header-anchor" href="#_3-2-ubo-实现" aria-label="Permalink to “3.2 UBO 实现”">​</a></h3><ul><li><strong><code>BloomParametersUbo</code></strong>：<code>bloomIntensity</code> / <code>bloomBlendThreshold</code> / <code>luminanceSensitivity</code></li><li><strong><code>BlurParametersUbo</code></strong>：<code>direction</code> / <code>sampleStepLength</code> / <code>colorMultiplier</code></li><li><strong><code>BloomPipelineParametersUbo</code></strong>：<code>resolution</code> / <code>frameIndex</code></li><li><strong><code>TransformsUbo</code></strong>：<code>projMat</code>（正交投影矩阵）</li></ul><p>所有 UBO 继承自 <code>UboObject</code>，通过 <code>DEFINITION</code> 静态常量声明布局。</p><hr><h2 id="_4-着色器与管线" tabindex="-1">4. 着色器与管线 <a class="header-anchor" href="#_4-着色器与管线" aria-label="Permalink to “4. 着色器与管线”">​</a></h2><h3 id="_4-1-着色器" tabindex="-1">4.1 着色器 <a class="header-anchor" href="#_4-1-着色器" aria-label="Permalink to “4.1 着色器”">​</a></h3><table tabindex="0"><thead><tr><th>文件</th><th>类型</th><th>作用</th></tr></thead><tbody><tr><td><code>blit.vsh</code></td><td>顶点</td><td>简单的全屏四边形变换，输出 UV</td></tr><tr><td><code>blur.fsh</code></td><td>片段</td><td>7 权重的高斯模糊（结合方向 <code>BlurDir</code> 与步长 <code>SampleStepLength</code>）</td></tr><tr><td><code>apply_bloom.fsh</code></td><td>片段</td><td>将泛光纹理按强度混合到游戏画面</td></tr><tr><td><code>down_sample.fsh</code></td><td>片段</td><td>4 像素取平均进行下采样</td></tr><tr><td><code>up_sample.fsh</code></td><td>片段</td><td>5×5 高斯核上采样，与前一帧混合</td></tr><tr><td><code>util.glsl</code></td><td>工具</td><td><code>saturate()</code>、<code>toneMap()</code> 辅助函数</td></tr></tbody></table><h3 id="_4-2-管线注册" tabindex="-1">4.2 管线注册 <a class="header-anchor" href="#_4-2-管线注册" aria-label="Permalink to “4.2 管线注册”">​</a></h3><p><code>ALRPipelines</code> 类使用 <code>@EventBusSubscriber</code> 自动注册。定义了 4 个管线（基于 <code>POST_PASS</code> 片段）：</p><ul><li><code>BLUR</code> – 模糊</li><li><code>APPLY_BLOOM</code> – 最终混合</li><li><code>DOWNSAMPLE</code> – 下采样</li><li><code>UPSAMPLE</code> – 上采样</li></ul><p>基础片段 <code>POST_PASS</code> 使用 <code>blit.vsh</code>，绑定 <code>Transforms</code> UBO 和 <code>DiffuseSampler</code>，禁用面剔除。</p><hr><h2 id="_5-集成到-minecraft-渲染" tabindex="-1">5. 集成到 Minecraft 渲染 <a class="header-anchor" href="#_5-集成到-minecraft-渲染" aria-label="Permalink to “5. 集成到 Minecraft 渲染”">​</a></h2><h3 id="_5-1-事件与入口" tabindex="-1">5.1 事件与入口 <a class="header-anchor" href="#_5-1-事件与入口" aria-label="Permalink to “5.1 事件与入口”">​</a></h3><p><code>ALRendering</code>（通过 <code>@Mod</code> 和 <code>@EventBusSubscriber</code>）：</p><ul><li>在 <code>RenderFrameEvent.Pre</code> 调用 <code>bloomPostEffect.beginFrame()</code>。</li><li>在 <code>RenderLevelStageEvent.AfterLevel</code> 调用 <code>bloomPostEffect.process(…)</code>，并创建 <code>FeatureRenderDispatcher</code> 以支持在泛光输入中提交模型。</li><li>在 <code>RegisterPipelineModifiersEvent</code> 注册 <code>REDIRECT_TO_BLOOM</code> 修饰符。</li></ul><h3 id="_5-2-mixin" tabindex="-1">5.2 Mixin <a class="header-anchor" href="#_5-2-mixin" aria-label="Permalink to “5.2 Mixin”">​</a></h3><ul><li><strong><code>MinecraftMixin</code></strong>： <ul><li>构造结束时调用 <code>ALRendering.createPipelines()</code> 初始化泛光实例。</li><li>窗口大小改变时恢复泛光纹理大小。</li></ul></li><li><strong><code>GuiRendererMixin</code></strong>： <ul><li>追踪每个 GUI 绘制元素对应的 <code>GuiElementRenderState</code>。</li><li>当元素实现 <code>LibGuiElementRenderState</code> 时，在绘制前将其 <code>bufferSlices()</code> 返回的 UBO 切片绑定到 RenderPass。</li></ul></li></ul><h3 id="_5-3-状态接口" tabindex="-1">5.3 状态接口 <a class="header-anchor" href="#_5-3-状态接口" aria-label="Permalink to “5.3 状态接口”">​</a></h3><ul><li><strong><code>LibGuiElementRenderState</code></strong>：扩展 <code>GuiElementRenderState</code>，提供 <code>Map&lt;String, GpuBufferSlice&gt; bufferSlices()</code>，允许 GUI 元素注入自定义 Uniform。</li><li><strong><code>LibQuadGuiElementRenderState</code></strong>：进一步为四边形元素提供便捷的视口计算 (<code>getBounds</code>) 和顶点构建方法 ( <code>buildVertices</code>)。</li></ul><hr><h2 id="_6-测试与调试" tabindex="-1">6. 测试与调试 <a class="header-anchor" href="#_6-测试与调试" aria-label="Permalink to “6. 测试与调试”">​</a></h2><p><code>ALRTest</code> 提供了简单示例：</p><ul><li><code>renderCarrotBloomed()</code>：渲染一个发光的胡萝卜，先绘制物品，再将其注册为 <code>BloomRenderCallback</code> 以产生泛光。</li><li><strong>开启调试</strong>：添加 JVM 属性 <code>-Danvillib.rendering.debugMode</code> 即可启用测试渲染（需在屏幕或世界中调用）。</li></ul><hr><h2 id="_7-使用指南摘要" tabindex="-1">7. 使用指南摘要 <a class="header-anchor" href="#_7-使用指南摘要" aria-label="Permalink to “7. 使用指南摘要”">​</a></h2><ol><li><strong>获取泛光实例</strong>：<code>ALRendering.getBloomPostEffect()</code>。</li><li><strong>添加泛光物体</strong>：<div class="language-java line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">bloomPostEffect.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">drawBloomed</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">((nodeCollector, poseStack) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    // 提交渲染到 nodeCollector</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">});</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div></li><li><strong>标记脏状态</strong>：每帧在 <code>beginFrame()</code> 后默认非脏，调用 <code>drawBloomed</code> 会自动标记脏，也可手动 <code>markDirty()</code>。</li><li><strong>自定义 UBO</strong>：继承 <code>UboObject&lt;T&gt;</code>，使用 <code>UboLayoutDefinition.create(...)</code> 定义字段布局，配合 <code>upload</code> 上传。</li><li><strong>GUI 元素注入 UBO</strong>：实现 <code>LibGuiElementRenderState</code>，在 <code>bufferSlices()</code> 中返回需要绑定的缓冲切片。</li></ol><hr><h2 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to “注意事项”">​</a></h2><ul><li>泛光效果依赖大量 RenderTarget 创建，请确保在客户端环境使用（模组限定 <code>dist = Dist.CLIENT</code>）。</li><li>所有 GPU 资源（Buffer, Sampler, Texture）由 <code>GpuDevice</code> 创建，生命周期跟随 <code>BloomPostEffect</code> 实例，通常在模组生命周期内保持。</li><li>目前泛光参数硬编码在 <code>BloomPostEffect</code> 中（如采样步长、混合阈值等），后续可通过配置屏幕调整。</li><li>Mixin 修改了 <code>GuiRenderer</code> 内部行为，与其它渲染修改模组可能产生兼容性冲突，需注意。</li></ul>`,61)])])}const p=o(t,[["render",l]]);export{u as __pageData,p as default};
